/** Strict source-free record boundary. Import validation always replays the supplied finite X/Y. */
export const SCHEMA = 'dual-array-record-v1';
export const REQUEST_SCHEMA = 'dual-array-request-v1';
export const LIMITS = Object.freeze({maxNa:64,maxNb:16,maxT:128,maxAngles:721,maxRanges:481,maxCandidates:90000,maxMacs:200000000,maxRequestBytes:2*1024*1024,maxRecordBytes:12*1024*1024,maxMemoryBytes:64*1024*1024,maxBudgetMs:120000,maxDepth:48});
export const SOURCE = Object.freeze({paper_id:'nearfield-double-array-ispac',fixed_source:'arxiv:2311.07722v1',scope:'bounded-downlink-Algorithm1-finite-X',reference_manifest_sha256:'c9b0259b4834dde60b842f479e3730a92fe1efabecc6122e278ce7c46acdde0b',contract_sha256:'44cdf804cebd9acb94d2306a3e40cf5df5c364ef778cd5a757917e24fe7f54fb',study_freeze_sha256:'8ded40ef96e2f1f57ca5b113056abeb95f35b81f0edaecbd4f74c3d5eff1f4d5',statistics_sha256:'e54cc91dbc25f25b48584dedd98b885305eed33e4e7bc2c22eeb6a8bdb98018b'});
export const CLAIMS = Object.freeze({original_Fig4_reproduction:false,continuous_global_ML:false,global_uniqueness_certified:false,target_detection_certified:false,whole_paper_reproduction:false,offline_study_recomputed:false});
export function assert(condition,message){if(!condition)throw new TypeError(message);}
export function keys(value,expected,path='object'){assert(value!==null&&typeof value==='object'&&!Array.isArray(value),`${path}: object required`);const actual=Reflect.ownKeys(value);assert(actual.length===expected.length&&expected.every(k=>Object.hasOwn(value,k))&&actual.every(k=>typeof k==='string'&&expected.includes(k)),`${path}: exact keys required (${expected.join(', ')})`);}
export function integer(value,min,max,path){assert(typeof value==='number'&&Number.isSafeInteger(value)&&value>=min&&value<=max,`${path}: integer in [${min}, ${max}] required`);return value;}
export function finite(value,path){assert(typeof value==='number'&&Number.isFinite(value),`${path}: finite number required`);return value;}
function boolean(value,path){assert(typeof value==='boolean',`${path}: boolean required`);}
function positive(value,path){finite(value,path);assert(value>0,`${path}: positive number required`);}
function hash(value,path){assert(typeof value==='string'&&/^[0-9a-f]{64}$/.test(value),`${path}: lower-case SHA256 required`);}
/** Copy only finite, accessor-free JSON, before the first asynchronous operation. */
export function snapshotJSON(input,maxBytes=LIMITS.maxRecordBytes){let roughBytes=0,nodes=0;const seen=new Set();const charge=n=>{roughBytes+=n;assert(roughBytes<=maxBytes,'JSON byte budget exceeded');};function copy(value,depth){assert(depth<=LIMITS.maxDepth,'JSON nesting budget exceeded');assert(++nodes<=maxBytes/2,'JSON node budget exceeded');if(value===null){charge(4);return null;}if(typeof value==='boolean'){charge(5);return value;}if(typeof value==='number'){finite(value,'JSON number');charge(String(value).length+1);return value;}if(typeof value==='string'){assert(value.length<=maxBytes,'JSON string budget exceeded');charge(value.length+2);return value;}assert(value&&typeof value==='object','finite JSON values only');assert(!seen.has(value),'cyclic JSON is forbidden');seen.add(value);let output;if(Array.isArray(value)){assert(value.length<=maxBytes/2,'JSON array budget exceeded');const own=Reflect.ownKeys(value);assert(own.length===value.length+1&&own.every(k=>k==='length'||(typeof k==='string'&&/^(0|[1-9][0-9]*)$/.test(k)&&Number(k)<value.length)),'dense JSON arrays without extra properties required');output=new Array(value.length);charge(2+value.length);for(let i=0;i<value.length;i++){const d=Object.getOwnPropertyDescriptor(value,String(i));assert(d&&d.enumerable&&'value'in d,'JSON accessors are forbidden');output[i]=copy(d.value,depth+1);}}else{assert(Object.getPrototypeOf(value)===Object.prototype||Object.getPrototypeOf(value)===null,'plain JSON objects required');output={};const own=Reflect.ownKeys(value);charge(2+own.length);for(const key of own){assert(typeof key==='string'&&!['__proto__','constructor','prototype'].includes(key),'unsupported JSON key');const d=Object.getOwnPropertyDescriptor(value,key);assert(d.enumerable&&'value'in d,'JSON accessors are forbidden');charge(key.length+3);output[key]=copy(d.value,depth+1);}}seen.delete(value);return Object.freeze(output);}const owned=copy(input,0);assert(new TextEncoder().encode(canonical(owned)).byteLength<=maxBytes,'JSON UTF-8 byte budget exceeded');return owned;}
function matrix(value,rows,cols,path){keys(value,['rows','cols','data'],path);integer(value.rows,1,LIMITS.maxNa,`${path}.rows`);integer(value.cols,1,LIMITS.maxT,`${path}.cols`);assert(value.rows===rows&&value.cols===cols,`${path}: matrix shape mismatch`);assert(Array.isArray(value.data)&&value.data.length===2*rows*cols,`${path}: interleaved matrix shape mismatch`);value.data.forEach((v,i)=>finite(v,`${path}.data[${i}]`));}
function grid(value,min,max,limit,path){assert(Array.isArray(value),`${path}: array required`);integer(value.length,1,limit,`${path}.length`);value.forEach((v,i)=>{finite(v,`${path}[${i}]`);assert(v>=min&&v<=max,`${path}: out of range`);if(i)assert(v>value[i-1],`${path}: strictly increasing required`);});}
/** Bounded literal finite-X MAC estimate is intentionally conservative and has no user override. */
export function preflightRequest(input){const request=snapshotJSON(input,LIMITS.maxRequestBytes);assert(request.mode==='scene'||request.mode==='observation','request.mode: scene or observation required');keys(request,['schema','mode','geometry','X','theta_grid_rad','range_grid_m','includeSurfaces',request.mode==='scene'?'scene':'Y'],'request');assert(request.schema===REQUEST_SCHEMA,'unsupported request schema');boolean(request.includeSurfaces,'includeSurfaces');const g=request.geometry;keys(g,['na','nb','wavelength','da','db'],'geometry');integer(g.na,1,LIMITS.maxNa,'geometry.na');integer(g.nb,2,LIMITS.maxNb,'geometry.nb');for(const k of ['wavelength','da','db'])positive(g[k],`geometry.${k}`);keys(request.X,['rows','cols','data'],'X');const T=integer(request.X.cols,1,LIMITS.maxT,'X.cols');matrix(request.X,g.na,T,'X');grid(request.theta_grid_rad,-Math.PI/2,Math.PI/2,LIMITS.maxAngles,'theta_grid_rad');grid(request.range_grid_m,Number.MIN_VALUE,Number.MAX_VALUE,LIMITS.maxRanges,'range_grid_m');if(request.mode==='observation')matrix(request.Y,g.nb,T,'Y');else{const s=request.scene;keys(s,['theta_rad','range_m','beta','sigma2','seed'],'scene');finite(s.theta_rad,'scene.theta_rad');assert(Math.abs(s.theta_rad)<=Math.PI/2,'scene.theta_rad outside broadside sector');positive(s.range_m,'scene.range_m');assert(Array.isArray(s.beta)&&s.beta.length===2,'scene.beta: complex pair required');s.beta.forEach(v=>finite(v,'scene.beta'));finite(s.sigma2,'scene.sigma2');assert(s.sigma2>=0,'scene.sigma2 must be nonnegative');integer(s.seed,0,0xffffffff,'scene.seed');}
const ntheta=request.theta_grid_rad.length,nrange=request.range_grid_m.length,candidates=ntheta*nrange,work=candidates*g.na*T;assert(candidates<=LIMITS.maxCandidates,'candidate work budget exceeded');assert(work<=LIMITS.maxMacs,'literal finite-X work budget exceeded');const memoryBytes=8*(12*g.na*T+20*g.nb*T+16*g.nb*g.nb+8*candidates+12*ntheta+8*nrange);assert(memoryBytes<=LIMITS.maxMemoryBytes,'working memory budget exceeded');return Object.freeze({request,work,memoryBytes,candidates,T});}
export function validateRequest(input){return preflightRequest(input).request;}
export function canonical(input){if(Object.is(input,-0))return '-0';if(input===null||typeof input!=='object')return JSON.stringify(input);if(Array.isArray(input))return '['+input.map(canonical).join(',')+']';return '{'+Object.keys(input).sort().map(k=>JSON.stringify(k)+':'+canonical(input[k])).join(',')+'}';}
export async function sha256Bytes(bytes){const value=await globalThis.crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(value),x=>x.toString(16).padStart(2,'0')).join('');}
export async function digest(input){const owned=snapshotJSON(input);return sha256Bytes(new TextEncoder().encode(canonical(owned)));}
function span(value,limit,path){assert(Array.isArray(value)&&value.length===2,`${path}: index pair required`);value.forEach(v=>integer(v,0,limit-1,path));assert(value[0]<=value[1],`${path}: ordered span required`);}
function estimate(value,request,joint){const p=joint?'joint':'two_stage',nt=request.theta_grid_rad.length,nr=request.range_grid_m.length;if(value?.status==='all-templates-null'){keys(value,['status','theta_rad','range_m'],p);assert(value.theta_rad===null&&value.range_m===null,`${p}: absent coordinates must be null`);return false;}keys(value,['status','theta_rad','range_m','theta_index','range_index','beta','score','profile_residual','ties','tie_index_span','angle_boundary','range_boundary'],p);assert(value.status==='numeric-estimate',`${p}: unknown status`);integer(value.theta_index,0,nt-1,`${p}.theta_index`);integer(value.range_index,0,nr-1,`${p}.range_index`);assert(value.theta_rad===request.theta_grid_rad[value.theta_index]&&value.range_m===request.range_grid_m[value.range_index],`${p}: estimate must match indexed grid`);assert(Array.isArray(value.beta)&&value.beta.length===2,`${p}.beta: pair required`);value.beta.forEach(v=>finite(v,`${p}.beta`));finite(value.score,`${p}.score`);assert(value.score>=0,`${p}.score must be nonnegative`);finite(value.profile_residual,`${p}.profile_residual`);integer(value.ties,1,joint?nt*nr:nr,`${p}.ties`);span(value.tie_index_span,joint?nt*nr:nr,`${p}.tie_index_span`);assert(value.ties<=value.tie_index_span[1]-value.tie_index_span[0]+1,`${p}: tie count exceeds span`);assert((joint?value.theta_index*nr+value.range_index:value.range_index)===value.tie_index_span[0],`${p}: tie policy requires lowest index`);boolean(value.angle_boundary,`${p}.angle_boundary`);boolean(value.range_boundary,`${p}.range_boundary`);assert(value.angle_boundary===(value.theta_index===0||value.theta_index===nt-1)&&value.range_boundary===(value.range_index===0||value.range_index===nr-1),`${p}: boundary flags inconsistent`);return true;}
export function validateResult(result,request){const nt=request.theta_grid_rad.length,nr=request.range_grid_m.length,g=request.geometry;const required=['two_stage','joint','waveform_numerical_rank','range_structurally_nonidentifiable','null_candidates','angle_eigengap','angle_relative_eigengap','angle_degenerate','eigenvalues','eigen_residual','hermitian_residual','orthogonality_residual','music_projector_equivalence_abs','angle_tie_count','angle_tie_index_span','evaluations','y_energy','stage_joint_row_max_abs_difference','joint_dominates','x_sha256','y_sha256','eigensolver','timing_seconds'];keys(result,request.includeSurfaces?[...required,'surfaces']:required,'result');const a=estimate(result.two_stage,request,false),b=estimate(result.joint,request,true);integer(result.waveform_numerical_rank,0,Math.min(g.na,request.X.cols),'waveform_numerical_rank');boolean(result.range_structurally_nonidentifiable,'range_structurally_nonidentifiable');assert(result.range_structurally_nonidentifiable===(result.waveform_numerical_rank<=1),'rank/nonidentifiability contradiction');integer(result.null_candidates,0,nt*nr,'null_candidates');if(result.null_candidates===nt*nr)assert(!a&&!b,'all-null candidates must have absent estimates');if(!b)assert(result.null_candidates===nt*nr,'absent joint estimate requires all candidates null');for(const k of ['angle_eigengap','angle_relative_eigengap','eigen_residual','hermitian_residual','orthogonality_residual','music_projector_equivalence_abs','y_energy']){finite(result[k],k);assert(result[k]>=0,`${k}: nonnegative required`);}boolean(result.angle_degenerate,'angle_degenerate');assert(result.angle_degenerate===(result.angle_relative_eigengap<=1e-10),'degeneracy flag inconsistent');assert(Array.isArray(result.eigenvalues)&&result.eigenvalues.length===g.nb,'eigenvalue shape');result.eigenvalues.forEach((v,i)=>{finite(v,'eigenvalue');if(i)assert(v>=result.eigenvalues[i-1],'sorted eigenvalues required');});integer(result.angle_tie_count,1,nt,'angle_tie_count');span(result.angle_tie_index_span,nt,'angle_tie_index_span');assert(result.angle_tie_count<=result.angle_tie_index_span[1]-result.angle_tie_index_span[0]+1,'angle tie count exceeds span');if(a)assert(result.two_stage.theta_index===result.angle_tie_index_span[0],'MUSIC tie policy inconsistent');keys(result.evaluations,['two_stage_music','two_stage_profile','joint_profile'],'evaluations');assert(result.evaluations.two_stage_music===nt&&result.evaluations.two_stage_profile===nr&&result.evaluations.joint_profile===nt*nr,'evaluation counts inconsistent');if(result.stage_joint_row_max_abs_difference!==null){finite(result.stage_joint_row_max_abs_difference,'stage_joint_row_max_abs_difference');assert(result.stage_joint_row_max_abs_difference>=0,'negative stage difference');}boolean(result.joint_dominates,'joint_dominates');assert(result.joint_dominates===(!a||!b||result.joint.score+1e-10*Math.max(1,Math.abs(result.two_stage.score))>=result.two_stage.score),'joint dominance flag inconsistent');hash(result.x_sha256,'x_sha256');hash(result.y_sha256,'y_sha256');keys(result.eigensolver,['converged','sweeps','offdiag_relative'],'eigensolver');boolean(result.eigensolver.converged,'eigensolver.converged');assert(result.eigensolver.converged&&result.eigen_residual<=1e-10&&result.orthogonality_residual<=1e-10,'unverified eigensolver result');integer(result.eigensolver.sweeps,0,100000,'eigensolver.sweeps');finite(result.eigensolver.offdiag_relative,'eigensolver.offdiag_relative');assert(result.eigensolver.offdiag_relative>=0,'negative eigensolver residual');assert(result.timing_seconds&&typeof result.timing_seconds==='object'&&!Array.isArray(result.timing_seconds)&&Object.keys(result.timing_seconds).length>0,'timing_seconds object');for(const v of Object.values(result.timing_seconds)){finite(v,'timing_seconds');assert(v>=0,'negative timing');}if(request.includeSurfaces){const s=result.surfaces;keys(s,['music','profile_scores','noise_projector','covariance'],'surfaces');assert(Array.isArray(s.music)&&s.music.length===nt,'MUSIC surface shape');s.music.forEach(v=>finite(v,'music'));assert(Array.isArray(s.profile_scores)&&s.profile_scores.length===nt*nr,'profile score surface shape');s.profile_scores.forEach(v=>{if(v!==null){finite(v,'profile score');assert(v>=0,'negative profile score');}});assert(s.profile_scores.filter(v=>v===null).length===result.null_candidates,'surface null-count mismatch');matrix(s.noise_projector,g.nb,g.nb,'noise_projector');matrix(s.covariance,g.nb,g.nb,'covariance');}return {numeric_estimates:Number(a)+Number(b),status:a&&b?'numeric-estimates':'absent-estimate'};}
const EXACT_NAMES=new Set(['theta_index','range_index','ties','angle_tie_count','waveform_numerical_rank','null_candidates','two_stage_music','two_stage_profile','joint_profile','sweeps','rows','cols','seed','na','nb','T','trial_count','summary_count','total_recorded_observations']);
/** Scientific comparisons are homogeneous in expected physical scale. A unit-sized
 * absolute tolerance must never erase tiny data, gain, score, or information.
 * FIM/CRB entries use parameter-local diagonal geometric scales, not a whole
 * matrix maximum that could hide a weak position block beside strong gain data. */
const DIMENSIONLESS_DIAGNOSTICS=new Set(['eigen_residual','hermitian_residual','orthogonality_residual','music_projector_equivalence_abs','angle_relative_eigengap','schur_projection_relative_residual','offdiag_relative','trace_relative_residual']);
function numericScale(values){let scale=0;for(const v of values){if(typeof v==='number')scale=Math.max(scale,Math.abs(v));else if(Array.isArray(v))scale=Math.max(scale,numericScale(v));}return scale;}
export function semanticEqual(actual,expected,path='record',contextScale){if(expected===null||typeof expected!=='object'){if(typeof expected==='number'){finite(actual,path);const name=path.split('.').at(-1),structural=EXACT_NAMES.has(name)||/tie_index_span\[\d+\]$/.test(path);if(/\.timing_seconds\.[^.]+$/.test(path)){assert(actual>=0,`${path}: negative timing`);return;}const scale=contextScale??Math.abs(expected),tolerance=DIMENSIONLESS_DIAGNOSTICS.has(name)?1e-11+1e-10*Math.abs(expected):1e-10*scale;assert(structural?actual===expected:Math.abs(actual-expected)<=tolerance,`${path}: numerical mismatch`);}else assert(actual===expected,`${path}: mismatch`);return;}assert(actual&&typeof actual==='object',`${path}: object required`);if(Array.isArray(expected)){assert(Array.isArray(actual)&&actual.length===expected.length,`${path}: array shape mismatch`);if(/\.(full_fim|position_information|schur_information|trace_full_fim|crb)$/.test(path)){expected.forEach((row,i)=>{assert(Array.isArray(actual[i])&&actual[i].length===row.length,`${path}: matrix shape mismatch`);row.forEach((v,j)=>semanticEqual(actual[i][j],v,`${path}[${i}][${j}]`,Math.max(Math.abs(v),Math.sqrt(Math.abs(expected[i][i]))*Math.sqrt(Math.abs(expected[j][j])))));});}else{const scale=contextScale??numericScale(expected);expected.forEach((v,i)=>semanticEqual(actual[i],v,`${path}[${i}]`,typeof v==='number'||Array.isArray(v)?scale:undefined));}}else{keys(actual,Object.keys(expected),path);Object.keys(expected).forEach(k=>semanticEqual(actual[k],expected[k],`${path}.${k}`,k==='profile_residual'&&typeof expected.score==='number'?Math.max(Math.abs(expected.score),Math.abs(expected[k])):undefined));}}
/** Bind each stored raw matrix to its own canonical little-endian bytes before
 * numerical replay; a scene's regenerated Y does not validate forged saved Y. */
export async function matrixFingerprint(value){const prefix=new TextEncoder().encode(`(${value.rows}, ${value.cols})|`),bytes=new Uint8Array(prefix.length+8*value.data.length),view=new DataView(bytes.buffer);bytes.set(prefix);for(let i=0;i<value.data.length;i++)view.setFloat64(prefix.length+8*i,value.data[i],true);return sha256Bytes(bytes);}
async function kernelRun(request,options){const run=options.runRequest??(await import('./kernel.mjs')).runRequest;return run(request,options.control);}
function provenance(kind){return {...SOURCE,execution:kind==='fresh-scene'?'fresh-single-scene':'raw-observation-replay',trial_count:1,claims:{...CLAIMS}};}
async function executionCheck(execution,request){keys(execution,['result','request','generation'],'execution');const raw=validateRequest(execution.request);assert(raw.mode==='observation','execution request must contain actual X/Y');for(const k of ['schema','geometry','X','theta_grid_rad','range_grid_m','includeSurfaces'])assert(canonical(raw[k])===canonical(request[k]),`execution.request.${k}: changed input`);if(request.mode==='observation'){assert(execution.generation===null,'raw observation cannot claim generation');assert(canonical(raw.Y)===canonical(request.Y),'raw Y changed during execution');}else assert(execution.generation&&typeof execution.generation==='object'&&!Array.isArray(execution.generation),'scene generation record required');const assessed=validateResult(execution.result,raw);const [xh,yh]=await Promise.all([matrixFingerprint(raw.X),matrixFingerprint(raw.Y)]);assert(execution.result.x_sha256===xh,'stored actual X fingerprint mismatch');assert(execution.result.y_sha256===yh,'stored actual Y fingerprint mismatch');return assessed;}
export async function makeRecord(input,options={}){const request=validateRequest(input),execution=snapshotJSON(await kernelRun(request,options));await executionCheck(execution,request);const kind=request.mode==='scene'?'fresh-scene':'raw-observation';const body={schema:SCHEMA,kind,provenance:provenance(kind),request,execution};return snapshotJSON({...body,record_sha256:await digest(body)});}
/** Integrity alone is never acceptance: fresh records require bounded semantic replay. */
export async function checkRecord(input,options={}){const record=snapshotJSON(input);if(record.kind==='historical-summary')return checkHistorical(record);keys(record,['schema','kind','provenance','request','execution','record_sha256'],'record');assert(record.schema===SCHEMA,'unsupported record schema');assert(record.kind==='fresh-scene'||record.kind==='raw-observation','unknown record kind');hash(record.record_sha256,'record_sha256');const {record_sha256,...body}=record;assert(await digest(body)===record_sha256,'record integrity mismatch');assert(canonical(record.provenance)===canonical(provenance(record.kind)),'provenance: exact source, count and claims required');const request=validateRequest(record.request);assert((request.mode==='scene')===(record.kind==='fresh-scene'),'kind/mode mismatch');const assessed=await executionCheck(record.execution,request);const rerun=snapshotJSON(await kernelRun(request,options));await executionCheck(rerun,request);semanticEqual(record.execution,rerun,'execution');return Object.freeze({status:assessed.status==='numeric-estimates'?'passed':'absent-estimate',semantic_valid:true,numeric_estimates:assessed.numeric_estimates,scope:record.kind==='fresh-scene'?'single-scene generator and finite-X/Y receiver replay':'finite-X/Y receiver replay; physical origin unverified',trial_count:1,offline_study_recomputed:false,record_sha256});}
export async function exportRecord(input,options={}){const owned=snapshotJSON(input);await checkRecord(owned,options);return canonical(owned)+'\n';}
export async function importRecord(text,options={}){assert(typeof text==='string','record text required');assert(text.length<=LIMITS.maxRecordBytes&&new TextEncoder().encode(text).byteLength<=LIMITS.maxRecordBytes,'record byte budget exceeded');const record=snapshotJSON(JSON.parse(text));const verification=await checkRecord(record,options);return Object.freeze({record,verification});}
/** Exact accepted bytes, not retyped statistics or a claimed successful browser experiment. */
export async function importHistoricalSummary(text){assert(typeof text==='string'&&text.length<=2*1024*1024,'historical statistics text budget');assert(await sha256Bytes(new TextEncoder().encode(text))===SOURCE.statistics_sha256,'historical statistics do not match the accepted source hash');const summary=snapshotJSON(JSON.parse(text));keys(summary,['schema','total_recorded_observations','cell_summaries','description'],'historical statistics');assert(summary.schema==='dual-array-all-trial-statistics-v1'&&summary.total_recorded_observations===14464&&Array.isArray(summary.cell_summaries)&&summary.cell_summaries.length===31,'historical summary dimensions mismatch');const body={schema:SCHEMA,kind:'historical-summary',provenance:{...SOURCE,execution:'stored-offline-summary',trial_count:14464,summary_count:31,claims:{...CLAIMS}},source_text:text};return snapshotJSON({...body,record_sha256:await digest(body)});}
async function checkHistorical(record){keys(record,['schema','kind','provenance','source_text','record_sha256'],'historical record');assert(record.schema===SCHEMA,'unsupported record schema');const expected=await importHistoricalSummary(record.source_text);semanticEqual(record,expected,'historical record');return Object.freeze({status:'historical-source-verified',semantic_valid:true,scope:'accepted stored offline summary; raw trials not replayed by this import',trial_count:14464,summary_count:31,offline_study_recomputed:false,record_sha256:record.record_sha256});}
